import {
  Brush,
  Category,
  History,
  LiveTv,
  PlayArrow,
  ShowChart,
  Stars,
  TaskAlt,
  Tv,
  VerifiedUser,
  Whatshot,
} from "@mui/icons-material";
import { groupToColour, type Measure, type Season, type Show, type Status } from "./types";
import {
  StatCard,
  StatList,
  type GridListLayout,
  type StatListBaseProps,
  StatSummary,
  TotalsBand,
  VitalsCard,
  YearVitalsPair,
} from "../common/Stats";
import { TopCategoryBand } from "../common/TopList";
import { GroupedStatList } from "../common/GroupedStatList";
import { Hero } from "../common/Hero";
import ShowCardMediaImage, { ShowFranchiseStrip } from "./CardMediaImage";
import { useShowStripSource } from "./franchiseContext";
import { showSubtitle } from "./cardData";
import { STYLES, statusToColour, styleToColour, type Scheme } from "../utils/types";
import { useScheme } from "../common/useScheme";
import { Stack } from "@mui/material";
import { inProgressBeyondHero } from "../common/statsData";
import type { ReactNode } from "react";
import { CURRENT_PLAINDATE, type YearNumber } from "../common/date";
import type { YearType } from "../common/filterReducer";
import { Section, StatBand } from "../common/SectionRail";
import { SHOW_SECTIONS } from "./sections";
import { stated } from "../common/population";
import {
  allTimeTotals,
  groupShowsBy,
  measureOf,
  showHeroStats,
  minutesPerEpisode,
  perShowAverages,
  recentlyWatched,
  showsInYear,
  showTopOptions,
  showFigures,
  statsCardLabelGroup,
  statsCardLabelShow,
  statsCardLabelRecentlyWatched,
  statsCardLabelWatching,
  yearlyAverages,
  type ShowTopOption,
} from "./statsData";
import { useSelectBox } from "../common/SelectBoxHook";
import "../utils/arrayUtils";
import { categoryKeys } from "../common/filterSchema";
import { showFilters } from "./filters";

const Stats = ({
  data,
  upTo,
  hasNow,
  hero,
  watching,
  measure,
  yearType,
  yearTo,
}: {
  data: Show[];
  /** The rows up to the scope's year whatever its reading, for the cards titled that way. */
  upTo: Show[];
  hasNow: boolean;
  hero?: Season;
  watching: Season[];
  measure: Measure;
  yearType: YearType;
  yearTo: YearNumber;
}) => {
  return (
    <Stack spacing={2}>
      {/* The page's "now": the season holding the last episode watched, promoted the way the games
          tab promotes the game in progress, with whatever is in flight in a compact strip below
          it. Whether there is a section at all is `Graphs`' own answer, passed down rather than
          asked again: the rail's chip is offered on that same value, and a chip pointing at an
          anchor the page never rendered is what two derivations of one test buy. */}
      {hasNow && (
        <Now
          hero={hero}
          watching={watching}
        />
      )}
      <Section id={SHOW_SECTIONS.vitals}>
        <StatBand>
          {/* The first card and the average beside it count `upTo` rather than `data`: the scope
              read as a ceiling, which is what a card titled "All time" or "Up to 2019" states
              under either reading — fed the "In 2026" rows, it would restate the in-year figures
              under the wrong words. The in-year card narrows `data`, which under that reading is
              already the year. */}
          <YearVitalsPair
            yearTo={yearTo}
            yearType={yearType}
            allTime={allTimeTotals(upTo)}
            inYear={showsInYear(data, yearTo)}
          />
          <StatSummary
            icon={<ShowChart />}
            title="Per Year"
            stats={yearlyAverages(upTo)}
          />
          <ShowAverage data={data} />
          <Vitals
            data={data}
            measure={measure}
          />
        </StatBand>
      </Section>
      <Section id={SHOW_SECTIONS.top}>
        <StatBand>
          <TopCategories
            data={data}
            measure={measure}
          />
        </StatBand>
      </Section>
      <Section id={SHOW_SECTIONS.explore}>
        <StatBand>
          <RecentlyWatched data={data} />
          <MostWatched
            data={data}
            measure={measure}
          />
        </StatBand>
      </Section>
    </Stack>
  );
};

const Now = ({ hero, watching }: { hero?: Season; watching: Season[] }) => (
  <Section id={SHOW_SECTIONS.now}>
    <Stack spacing={2}>
      {hero && <ShowHero season={hero} />}
      {/* The two answer different questions — what was watched last, and what is still open — and
          may or may not name the same season. The strip is every open season, the hero's own
          included where the sheet has left it open; a hero the sheet has closed is not in it,
          though an open season of that same show still is. */}
      {inProgressBeyondHero(watching, hero) && (
        <StatBand>
          <CurrentlyWatching watching={watching} />
        </StatBand>
      )}
    </Stack>
  </Section>
);

/** The season holding the last episode watched. */
const ShowHero = ({ season }: { season: Season }) => {
  const scheme = useScheme();
  const hasStrip = useShowStripSource(season.show) !== undefined;

  return (
    <Hero
      item={season}
      MediaComponent={ShowCardMediaImage}
      shape="poster"
      // Watching a season the sheet has left open, from the day it began, as the other tabs state
      // a game or a book in hand; finished on the day the sheet closed it otherwise.
      activity={
        season.endDate ? { did: "Finished", on: season.endDate } : { doing: "Watching", since: season.startDate }
      }
      // The season with the show, as the Omnibus's Now card names it: nothing else on the hero says
      // which season it is on, and the episode count stands among the figures.
      title={`${season.show.name} S${season.s}`}
      subtitle={showSubtitle(season.show, scheme)}
      stats={showHeroStats(season, CURRENT_PLAINDATE)}
      // Only where there is a strip, so the panel lays its lower edge out for what it holds.
      strip={
        hasStrip && (
          <ShowFranchiseStrip
            show={season.show}
            season={season}
            variant="hero"
          />
        )
      }
    />
  );
};

/** The one band saying what the library is made of, dense enough to scan past. */
const Vitals = ({ data, measure }: { data: Show[]; measure: Measure }) => {
  const scheme = useScheme();

  const statusList: Status[] = ["Watching", "Up To Date", "Ended", "Cancelled", "Abandoned"];
  const measureFunc = (shows: Show[]) => measureOf(shows, measure);

  return (
    <VitalsCard>
      <TotalsBand
        title={"Status"}
        icon={<TaskAlt />}
        data={data}
        measureFunc={measureFunc}
        group={statusList}
        groupOf={(show) => show.status}
        groupToColour={(ele: Status) => statusToColour({ status: ele }, scheme)}
        measureLabel={measure}
      />
      <TotalsBand
        title={"Style"}
        icon={<Brush />}
        data={data}
        measureFunc={measureFunc}
        // The shared vocabulary in its own order, which is also what the filter's chips offer.
        group={STYLES}
        groupOf={(show) => show.style}
        groupToColour={(style: string) => styleToColour(style, scheme)}
        measureLabel={measure}
      />
    </VitalsCard>
  );
};

const ShowAverage = ({ data }: { data: Show[] }) => {
  const { seasons, episodes, hours } = perShowAverages(data);
  return (
    <StatCard
      icon={<LiveTv />}
      title="Per Show"
      content={[
        ["Seasons", seasons],
        ["Episodes", episodes],
        ["Hours", hours],
        ["Min / Ep", minutesPerEpisode(data)],
      ]}
    />
  );
};

const TopCategories = ({ data, measure }: { data: Show[]; measure: Measure }) => {
  const scheme = useScheme();

  return (
    <TopCategoryBand
      defaults={["genre", "network", "franchise"]}
      options={showTopOptions}
      icons={optionIcons}
      groups={(option) => groupShowsBy(data, option, measure)}
      colourOf={(option, top: Show) => groupToColour(option, top, scheme)}
      measureLabel={measure}
      categories={categoryKeys(showFilters)}
    />
  );
};

const optionIcons: Record<ShowTopOption, ReactNode> = {
  genre: <Category />,
  network: <Tv />,
  franchise: <Stars />,
  style: <Brush />,
  status: <TaskAlt />,
  certificate: <VerifiedUser />,
};

const RecentlyWatched = ({ data }: { data: Show[] }) => {
  const scheme = useScheme();

  const recent = recentlyWatched(data);
  return (
    <ShowStatList
      icon={<History />}
      title="Recently Watched"
      content={recent}
      chipComponent={({ show }) => showStatusChip(show, scheme)}
      labelComponent={statsCardLabelRecentlyWatched}
    />
  );
};

const mostWatchedOptions = ["name", ...showTopOptions] as const;

const MostWatched = ({ data, measure }: { data: Show[]; measure: Measure }) => {
  const [option, controls] = useSelectBox(mostWatchedOptions, "name", "By");

  if (option === "name") {
    return (
      <MostWatchedShows
        data={data}
        controls={controls}
      />
    );
  }
  return (
    <MostWatchedCategory
      data={data}
      measure={measure}
      controls={controls}
      category={option}
    />
  );
};

const MostWatchedShows = ({ data, controls }: { data: Show[]; controls: ReactNode }) => {
  const most = data.filter((show) => show.minutes).sortByKey("minutes");
  return (
    <ShowsStatList
      controls={controls}
      icon={<Whatshot />}
      title="Most Watched"
      content={most}
      labelComponent={statsCardLabelShow}
      // A strip card has room for one row, and on this list it is the figures rather than the
      // seasons: the hours are what the list is ranked by.
      captionOf={showFigures}
    />
  );
};

const MostWatchedCategory = ({
  data,
  measure,
  category,
  controls,
}: {
  data: Show[];
  measure: Measure;
  category: ShowTopOption;
  controls: ReactNode;
}) => {
  const scheme = useScheme();

  return (
    <GroupedStatList
      icon={<Whatshot />}
      controls={controls}
      title="Most Watched"
      option={category}
      groups={groupShowsBy(data, category, measure)}
      labelComponent={(group) => statsCardLabelGroup(group.name, stated(group.count, measure))}
      colourOf={(top) => groupToColour(category, top, scheme)}
      MediaComponent={ShowCardMediaImage}
      dialogSort={(shows) => shows.toSorted((a, b) => b.minutes - a.minutes)}
      nameOf={(show) => show.name}
      dialogLabelComponent={statsCardLabelShow}
      dialogChipComponent={(show) => showStatusChip(show, scheme)}
      {...showStatListSharedProps}
    />
  );
};

const CurrentlyWatching = ({ watching }: { watching: Season[] }) => {
  const scheme = useScheme();

  return (
    <ShowStatList
      icon={<PlayArrow />}
      title="Currently Watching"
      content={watching}
      // One badge saying how far into the show this season is, in the colour every chart paints
      // its status in. It reads "still going" on almost every card here, and that is the point of
      // drawing it: a season the sheet has left open under a status saying the show is done with
      // is a row nothing else on the page marks.
      chipComponent={(season) => ({ label: `S${season.s}E${season.e}`, colour: statusToColour(season.show, scheme) })}
      wrap={false}
      width={[12, 12, 12]}
      pictureWidth={[6, 4, 3, 2]}
      labelComponent={(season) => statsCardLabelWatching(season, CURRENT_PLAINDATE)}
    />
  );
};

/** The corner badge naming a show's status, in the colour that vocabulary wears everywhere on the tab. */
const showStatusChip = (show: Show, scheme: Scheme) => ({ label: show.status, colour: statusToColour(show, scheme) });

// Reserved so lazily-loaded artwork holds its height: a dialog of cards reserving nothing all
// sits inside the viewport at once and fetches every image immediately. The strip holds the
// shape firmly rather than yielding to each file, which `common/Stats.tsx` explains at the site
// that decides it.
const showStatListSharedProps: Pick<StatListBaseProps<Show>, "shape" | "width"> & GridListLayout = {
  shape: "poster",
  // Two lists to the band at `md`, as every tab stands its Recently and Most lists, with two posters
  // to a row inside one at `md` and three from `lg`: three at 900px are 133px each, where a card's
  // date and "days in" cannot share a footer line.
  width: [12, 12, 6],
  pictureWidth: [6, 4, 6, 4],
  dialogPictureWidth: [6, 4, 2],
};

const ShowStatList = (
  props: Omit<StatListBaseProps<Season>, "MediaComponent" | "nameComponent" | "width"> &
    Partial<Pick<StatListBaseProps<Season>, "width"> & Pick<GridListLayout, "pictureWidth">>,
) => {
  return (
    <StatList
      MediaComponent={ShowCardMediaImage}
      nameComponent={(entry) => entry.show.name + entry.s}
      {...showStatListSharedProps}
      {...props}
    />
  );
};

/** The Show-typed sibling of `ShowStatList`, for the lists whose rows are whole shows. */
const ShowsStatList = (
  props: Omit<StatListBaseProps<Show>, "MediaComponent" | "nameComponent" | "chipComponent" | "width">,
) => {
  const scheme = useScheme();

  return (
    <StatList
      MediaComponent={ShowCardMediaImage}
      nameComponent={(entry) => entry.name}
      chipComponent={(show) => showStatusChip(show, scheme)}
      {...showStatListSharedProps}
      {...props}
    />
  );
};

export default Stats;
